/* From Uiverse.io by n-jaisabai - Tags: button */
.__UIV_SCOPE__ .button {
  background: radial-gradient(ellipse at top, white, blue, black, black);
  color: white;
  position: relative;
  background-size: 130% 130%;
  background-position: center center;
  padding: 15px 30px;
}

.__UIV_SCOPE__ .button:hover {
  background: radial-gradient(ellipse at top, white, blue, black, black);
  animation: gradient 4s;
  animation-fill-mode: forwards;
  /* background-position: center center; */
}

.__UIV_SCOPE__ .button:hover:after {
  content: "";
  position: absolute;
  inset: -.625em;
  background: radial-gradient(ellipse at top, white, blue, black, black);
  /* background-position: center center; */
  filter: blur(1.5em);
  z-index: -1;
  animation: gradient 4s;
  animation-fill-mode: forwards;
}

@keyframes gradient {
  0% {
    background-size: 130% 130%;
  }

  100% {
    background-size: 200% 200%;
  }
}
